def backfill_issue_lineage(apps, schema_editor):
    """只回填原始外键或审计 issue_ids 能证明的归属；不按品名/时间猜提交。"""
    db = schema_editor.connection.alias
    Issue = apps.get_model('reviews', 'Issue')
    AuditEvent = apps.get_model('reviews', 'AuditEvent')
    audited = {}
    for event in AuditEvent.objects.using(db).filter(
        action__in=('task.returned', 'decision.returned'), version__isnull=False,
    ).select_related('version').iterator():
        details = event.details if isinstance(event.details, dict) else {}
        issue_ids = details.get('issue_ids', [])
        if not isinstance(issue_ids, list) or event.version.task_id != event.task_id:
            continue
        for issue_id in issue_ids:
            audited.setdefault(str(issue_id), set()).add((event.task_id, event.version_id))

    rows = Issue.objects.using(db).select_related('item__version', 'run__version', 'run__submission')
    for issue in rows.iterator():
        candidates = set(audited.get(str(issue.pk), ()))
        if issue.item_id:
            candidates.add((issue.item.version.task_id, issue.item.version_id))
        if issue.run_id:
            candidates.add((issue.run.task_id, issue.run.version_id))
            candidates.add((issue.run.version.task_id, issue.run.version_id))
        if len(candidates) != 1:
            continue
        task_id, version_id = candidates.pop()
        if task_id != issue.task_id:
            continue
        updates = {'version_id': version_id}
        if issue.run_id and issue.run.submission_id:
            submission = issue.run.submission
            if submission.task_id == task_id and submission.version_id == version_id:
                updates['submission_id'] = submission.pk
        Issue.objects.using(db).filter(pk=issue.pk).update(**updates)


